CREATE TABLE `dim_date` (
  `date_id` int NOT NULL,
  `full_date` date DEFAULT NULL,
  `year` int DEFAULT NULL,
  `quarter` int DEFAULT NULL,
  `quarter_label` varchar(20) DEFAULT NULL,
